with a as(select distinct on(x.announcement_id)x.announcement_id,x.supply_org org,coalesce(m.std_type,x.housing_type)std,extract(year from coalesce(x.announcement_date,x.created_at::date))::int yr from announcements x left join housing_type_map m on m.source_table='announcements' and m.source=x.source and m.housing_type=x.housing_type order by x.announcement_id,(x.source='LH')desc,x.created_at desc),y as(select p.announcement_id,regexp_replace(p.content_raw,'\s+',' ','g')t,coalesce(r.class_name,c.class_name)cls,a.org,a.std from announcement_policies p join a using(announcement_id) left join policy_row_classes r on r.policy_id=p.id and r.axis='standard' left join policy_category_classes c on c.category=p.category and c.axis='standard' where a.yr=2026)select json_build_object('anns',(select count(distinct announcement_id) from y where cls='이주·주거상향'),'by_std',(select json_object_agg(std,n) from(select std,count(distinct announcement_id)n from y where cls='이주·주거상향' group by 1)q),'넓은주택',(select count(distinct announcement_id) from y where cls='이주·주거상향' and t~'넓은[^.]{0,40}(이주|변경)'),'넓은주택_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='이주·주거상향' and t~'넓은[^.]{0,40}(이주|변경)' order by 1 desc limit 3)q),'2세미만',(select count(distinct announcement_id) from y where cls='이주·주거상향' and t~'2세\s*미만'),'2세미만_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='이주·주거상향' and t~'2세\s*미만' order by 1 desc limit 3)q),'2세이하',(select count(distinct announcement_id) from y where cls='이주·주거상향' and t~'2세\s*이하'),'2세이하_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='이주·주거상향' and t~'2세\s*이하' order by 1 desc limit 3)q),'후순위예비',(select count(distinct announcement_id) from y where cls='이주·주거상향' and t~'후순위\s*예비'),'후순위예비_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='이주·주거상향' and t~'후순위\s*예비' order by 1 desc limit 3)q),'같은시군구',(select count(distinct announcement_id) from y where cls='이주·주거상향' and t~'동일한\s*시\s*·?\s*군\s*·?\s*구'),'같은시군구_ex',(select json_agg(i) from(select distinct announcement_id i from y where cls='이주·주거상향' and t~'동일한\s*시\s*·?\s*군\s*·?\s*구' order by 1 desc limit 3)q))j;
